//! The Salsa database: source files and the program made of them are its inputs, and every
//! analysis is a query over them.
//!
//! The constructors, getters and setters below are generated by Salsa's macros, which do not
//! carry documentation; the structs and fields say what they are.
#![allow(missing_docs)]

/// A source file.
#[salsa::input(debug)]
pub struct SourceFile {
    /// The file's path, as shown in diagnostics.
    #[returns(ref)]
    pub path: String,
    /// The file's text.
    #[returns(ref)]
    pub text: String,
}

/// A program: the files of one or more mods, each the module its path in its mod makes it
/// (`modules.md`), and the mods with the dependencies between them. The first mod is the one
/// being built; the others are its dependencies, directly or not. The root input of every query.
#[salsa::input(debug)]
pub struct Program {
    /// The files, by their index (a [`FileId`]).
    #[returns(ref)]
    pub files: Vec<ProgramFile>,
    /// The mods, by their index.
    #[returns(ref)]
    pub mods: Vec<ModInfo>,
}

/// A file's index in its [`Program`].
pub type FileId = u32;

/// A file of a program, and the module it is.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct ProgramFile {
    /// The file.
    pub source: SourceFile,
    /// The mod it belongs to, by index.
    pub mod_: u32,
    /// The module's path in its mod: empty for the root module, `["book", "levels"]` for
    /// `book/levels.moddil`.
    pub module: Vec<String>,
    /// Whether it is an executable's main module (`[[exe]] main` in the manifest).
    pub exe: bool,
}

/// A mod of a program.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct ModInfo {
    /// Its name, as its manifest gives it.
    pub name: String,
    /// The mods it depends on: the name it calls each by, and the mod's index.
    pub deps: Vec<(String, u32)>,
    /// Whether it is a stub (`mod.stub.1`).
    pub stub: bool,
    /// Whether it may use `unsafe` blocks: its manifest declares the capability (`mod.caps.1`).
    pub unsafe_ok: bool,
    /// Whether it may name `core::os`: its manifest declares the `os` capability (`os.cap.1`).
    pub os_ok: bool,
}

impl Program {
    /// The program of one file, which is the root module of a mod of its own.
    pub fn single(db: &dyn Db, path: String, text: String) -> Program {
        let source = SourceFile::new(db, path, text);
        Program::new(
            db,
            vec![ProgramFile {
                source,
                mod_: 0,
                module: Vec::new(),
                exe: false,
            }],
            vec![ModInfo {
                name: String::new(),
                deps: Vec::new(),
                stub: false,
                unsafe_ok: false,
                os_ok: false,
            }],
        )
    }

    /// The program `project` describes: its files and its mods, as the compiler's input.
    pub fn of_project(db: &dyn Db, project: &moddil_project::Project) -> Program {
        let files = project
            .files
            .iter()
            .map(|f| ProgramFile {
                source: SourceFile::new(db, f.display.clone(), f.text.clone()),
                mod_: f.mod_,
                module: f.module.clone(),
                exe: f.exe,
            })
            .collect();
        let mods = project
            .mods
            .iter()
            .map(|m| ModInfo {
                name: m.name.clone(),
                deps: m.deps.clone(),
                stub: m.stub,
                unsafe_ok: m.unsafe_ok,
                os_ok: m.os_ok,
            })
            .collect();
        Program::new(db, files, mods)
    }
}

/// Something with a body: a function or a test, by its position among the program's items of
/// that kind.
#[salsa::interned]
pub struct Owner<'db> {
    /// The program the item is in.
    #[returns(copy)]
    pub program: Program,
    /// Which item.
    #[returns(copy)]
    pub item: Item,
}

/// A function or a test, by its index in the program's [`ItemTree`](crate::ItemTree), or a
/// closure in one's body.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Item {
    /// `fn`.
    Fn(u32),
    /// `test`.
    Test(u32),
    /// A closure: the index of the function (or, if the flag is set, test) whose body it is
    /// written in, and its expression's index in that body. Its body has its own MIR; it is
    /// checked with the body it is in.
    Closure(u32, bool, u32),
}

impl Item {
    /// The function or test whose body this is, or is written in.
    pub fn owner(self) -> Item {
        match self {
            Item::Closure(i, false, _) => Item::Fn(i),
            Item::Closure(i, true, _) => Item::Test(i),
            item => item,
        }
    }

    /// The closure at expression `expr` of the body of `owner` (a function or test).
    pub fn closure(owner: Item, expr: u32) -> Item {
        match owner.owner() {
            Item::Test(i) => Item::Closure(i, true, expr),
            Item::Fn(i) | Item::Closure(i, _, _) => Item::Closure(i, false, expr),
        }
    }
}

/// The queries `moddil-sema` defines need a database implementing this.
#[salsa::db]
pub trait Db: salsa::Database {
    /// What evaluates a tag while the program is collected (`comptime.tag.fields.2`), if
    /// anything does: without one, a tagged literal has no fields.
    fn evaluator(&self) -> Option<&dyn Evaluator> {
        None
    }
}

/// Evaluates a tag while a program is collected, for its literal's fields
/// (`comptime.tag.fields.2`). `moddil-interp` gives one; sema cannot run code itself.
pub trait Evaluator: Send + Sync + std::panic::RefUnwindSafe {
    /// `TagFields::field_names` of the value of the tag `request` names, called with its
    /// literal's text, in a program of the tag's mod and its dependencies.
    fn tag_fields(&self, request: &TagRequest) -> TagAnswer;
}

/// A tag to evaluate for its literal's fields: the program of the tag's mod (mod 0) and its
/// dependencies, the tag, and the literal's text.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct TagRequest {
    /// The program's files: each one's path, text, mod and module path.
    pub files: Vec<(String, String, u32, Vec<String>)>,
    /// Its mods.
    pub mods: Vec<ModInfo>,
    /// The module the tag is in, by its path in mod 0.
    pub module: Vec<String>,
    /// The tag's name.
    pub tag: String,
    /// The literal's text, as the tag is called with it.
    pub text: String,
}

/// What evaluating a tag for its fields gave.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum TagAnswer {
    /// The fields: each one's name, and whether every reading has it.
    Fields(Vec<(String, bool)>),
    /// A `compile_error` (`comptime.error.1`): its message, and the bytes of the text it names.
    CompileError(String, i64, i64),
    /// Another failure (a trap, fuel run out, or the tag's program not compiling).
    Failed(String),
}

/// The database: holds the inputs and memoises every query.
#[salsa::db]
#[derive(Clone, Default)]
pub struct Database {
    storage: salsa::Storage<Self>,
    evaluator: Option<std::sync::Arc<dyn Evaluator>>,
}

impl Database {
    /// A database whose tags `evaluator` evaluates while programs are collected.
    pub fn with_evaluator(evaluator: std::sync::Arc<dyn Evaluator>) -> Database {
        Database {
            storage: salsa::Storage::default(),
            evaluator: Some(evaluator),
        }
    }
}

#[salsa::db]
impl salsa::Database for Database {}

#[salsa::db]
impl Db for Database {
    fn evaluator(&self) -> Option<&dyn Evaluator> {
        self.evaluator.as_deref()
    }
}
